:"12"},{"n":"DB RDL","r":"12"},{"n":"Bird dog","r":"30"}]}]}]},{"programa":"HEALTHY","nivel":"AVANZADO","sexo":"hombre","nombre":"DEMO HEALTHY HOMBRE AVANZADO","sesiones":[{"numero":1,"zona":"LOWER","nombre":"DEMO LOWER BODY","bloques":[{"bloque":"B1","rol":"fuerza_principal","etiqueta":"PRINCIPAL","sets":3,"descanso":75,"ej":[{"n":"DB Goblet squat","r":"12"},{"n":"DB RDL","r":"12"}]},{"bloque":"B2","rol":"cierre_accesorio","etiqueta":"COMPLEMENTO","sets":3,"descanso":60,"ej":[{"n":"Leg press 45","r":"12"},{"n":"Prone leg curl machine","r":"12"},{"n":"Full plank iso","r":"30"}]}]},{"numero":2,"zona":"UPPER","nombre":"DEMO UPPER BODY","bloques":[{"bloque":"B1","rol":"fuerza_principal","etiqueta":"PRINCIPAL","sets":3,"descanso":75,"ej":[{"n":"DB Incline press","r":"12"},{"n":"DB Chest-supported row","r":"12"}]},{"bloque":"B2","rol":"cierre_accesorio","etiqueta":"COMPLEMENTO","sets":3,"descanso":60,"ej":[{"n":"High row machine","r":"12"},{"n":"DB Biceps curl","r":"12"},{"n":"Full plank iso","r":"30"}]}]},{"numero":3,"zona":"FULL","nombre":"DEMO FULL BODY","bloques":[{"bloque":"B1","rol":"fuerza_principal","etiqueta":"PRINCIPAL","sets":3,"descanso":75,"ej":[{"n":"DB Incline press","r":"12"},{"n":"DB Goblet squat","r":"12"}]},{"bloque":"B2","rol":"cierre_accesorio","etiqueta":"COMPLEMENTO","sets":3,"descanso":60,"ej":[{"n":"DB Chest-supported row","r":"12"},{"n":"DB RDL","r":"12"},{"n":"Full plank iso","r":"30"}]}]}]}]$json$::jsonb;
  p jsonb; s jsonb; b jsonb; e jsonb;
  v_pid uuid; v_sid uuid; v_bid uuid; v_eid uuid; v_ord int; v_falta text;
begin
  perform set_config('koach.sync','1',true);
  select string_agg(distinct x, ', ') into v_falta
    from jsonb_array_elements(d) p2, jsonb_array_elements(p2->'sesiones') s2, jsonb_array_elements(s2->'bloques') b2,
         jsonb_array_elements(b2->'ej') e2, lateral (select e2->>'n' x) q
   where not exists (select 1 from ejercicios where nombre = x and activo);
  if v_falta is not null then raise exception 'DEMO: ejercicios que no están en la biblioteca: %', v_falta; end if;

  delete from bloque_ejercicios where bloque_id in (select b.id from bloques b join sesiones_protocolo sp on sp.id=b.sesion_id join protocolos pr on pr.id=sp.protocolo_id where pr.estado='demo' and pr.socio_id is null);
  delete from bloques where sesion_id in (select sp.id from sesiones_protocolo sp join protocolos pr on pr.id=sp.protocolo_id where pr.estado='demo' and pr.socio_id is null);
  delete from sesiones_protocolo where protocolo_id in (select id from protocolos where estado='demo' and socio_id is null);
  delete from protocolos where estado='demo' and socio_id is null;

  for p in select * from jsonb_array_elements(d) loop
    insert into protocolos(programa, nivel, sexo, nombre, ciclo_semanas, socio_id, estado, variante, activo)
      values ((p->>'programa')::programa_tipo, (p->>'nivel')::nivel_tipo, (p->>'sexo')::user_sex, p->>'nombre', 1, null, 'demo', 1, true)
      returning id into v_pid;
    for s in select * from jsonb_array_elements(p->'sesiones') loop
      insert into sesiones_protocolo(protocolo_id, numero, nombre, objetivo, semana, publicado)
        values (v_pid, (s->>'numero')::int, s->>'nombre', s->>'zona', 1, true) returning id into v_sid;
      for b in select * from jsonb_array_elements(s->'bloques') loop
        insert into bloques(sesion_id, bloque, rol, sets, descanso_segundos, descanso_seg, etiqueta)
          values (v_sid, (b->>'bloque')::bloque_tipo, (b->>'rol')::bloque_rol, (b->>'sets')::int, (b->>'descanso')::int, (b->>'descanso')::int, b->>'etiqueta')
          returning id into v_bid;
        v_ord := 0;
        for e in select * from jsonb_array_elements(b->'ej') loop
          v_ord := v_ord + 1;
          select id into v_eid from ejercicios where nombre = e->>'n' and activo limit 1;
          insert into bloque_ejercicios(bloque_id, ejercicio_id, orden, reps_txt, es_ancla) values (v_bid, v_eid, v_ord, e->>'r', false);
        end loop;
      end loop;
    end loop;
  end loop;
  perform set_config('koach.sync','0',true);
end
$carga$;

